#include "playerData.h"

#include <utility>

PlayerData::PlayerData() = default;

PlayerData::PlayerData(int id, QString name, const QVector<TileData> &tiles)
    : playerId(id), playerName(std::move(name)), centralTiles(tiles)
{
}

auto PlayerData::getPlayerId() const -> int
{
    return playerId;
}

auto PlayerData::getPlayerName() const -> const QString &
{
    return playerName;
}

auto PlayerData::getCentralTiles() const -> const QVector<TileData> &
{
    return centralTiles;
}

auto PlayerData::toVariant() const -> QVariant
{
    QVariantMap map;
    map["playerId"]   = playerId;
    map["playerName"] = playerName;

    QVariantList tilesList;
    for (const auto &tile : centralTiles)
    {
        tilesList.append(tile.toVariant());
    }
    map["centralTiles"] = tilesList;

    return map;
}

void PlayerData::fromVariant(const QVariant &variant)
{
    QVariantMap map = variant.toMap();
    playerId        = map["playerId"].toInt();
    playerName      = map["playerName"].toString();

    centralTiles.clear();
    QVariantList centralTilesList = map["centralTiles"].toList();

    for (const QVariant &centralTile : centralTilesList)
    {
        TileData tileData;
        tileData.fromVariant(centralTile);
        centralTiles.append(tileData);
    }
}

#include "tileData.h"

TileData::TileData() = default;

TileData::TileData(int row, int col) : row(row), col(col)
{
    placedTile  = false;
    placedToken = "";
    rotation    = 0;
}

TileData::~TileData() = default;

auto TileData::getRow() const -> int
{
    return row;
}

auto TileData::getCol() const -> int
{
    return col;
}

auto TileData::getPlacedTile() const -> bool
{
    return placedTile;
}

void TileData::setPlacedTile(bool newPlacedTile)
{
    placedTile = newPlacedTile;
}

auto TileData::getIsValid() const -> bool
{
    return isValid;
}

void TileData::setIsValid(bool newIsValid)
{
    isValid = newIsValid;
}

auto TileData::getPlacedToken() const -> QString
{
    return placedToken;
}

void TileData::setPlacedToken(const QString &newPlacedToken)
{
    placedToken = newPlacedToken;
}

auto TileData::getAnimals() const -> QVector<QString>
{
    return animals;
}

void TileData::setAnimals(const QVector<QString> &newAnimals)
{
    animals = newAnimals;
}

auto TileData::getHabitats() const -> QVector<QString>
{
    return habitats;
}

void TileData::setHabitats(const QVector<QString> &newHabitats)
{
    habitats = newHabitats;
}

auto TileData::getRotation() const -> int
{
    return rotation;
}

void TileData::setRotation(int newRotation)
{
    rotation = newRotation;
}

auto TileData::getId() const -> int
{
    return id;
}

void TileData::setId(int newId)
{
    id = newId;
}

auto TileData::toVariant() const -> QVariant
{
    QVariantMap map;
    map.insert("id", id);
    map.insert("row", row);
    map.insert("col", col);
    map.insert("placedTile", placedTile);
    map.insert("isValid", isValid);
    map.insert("placedToken", placedToken);
    map.insert("rotation", rotation);

    QVariantList listAnimals;
    for (const auto &animal : animals)
    {
        listAnimals.append(animal);
    }
    map.insert("animals", listAnimals);

    QVariantList listHabitats;
    for (const auto &habitat : habitats)
    {
        listHabitats.append(habitat);
    }
    map.insert("habitats", listHabitats);

    return map;
}

void TileData::fromVariant(const QVariant &variant)
{
    QVariantMap map = variant.toMap();
    id          = map.value("id").toInt();
    row         = map.value("row").toInt();
    col         = map.value("col").toInt();
    placedTile  = map.value("placedTile").toBool();
    isValid     = map.value("isValid").toBool();
    placedToken = map.value("placedToken").toString();
    rotation    = map.value("rotation").toInt();

    animals.clear();

    QVariantList listAnimals = map.value("animals").toList();
    animals.reserve(listAnimals.size());

    for (const QVariant &animal : listAnimals)
    {
        animals.push_back(animal.toString());
    }

    habitats.clear();

    QVariantList listHabitats = map.value("habitats").toList();
    habitats.reserve(listHabitats.size());

    for (const QVariant &habitat : listHabitats)
    {
        habitats.push_back(habitat.toString());
    }
}

void TileData::setIndex(int newIndex)
{
    index = newIndex;
}

auto TileData::getIndex() const -> int
{
    return index;
}
